// This message is used to acknowledge the request that recipes be deleted or deselected.
//
// Body: L[2]{ U1[rmack] L[n]{ <errors>... } }.
//
// Exception: p = 0 if and only if RMACK indicates no errors.
func S15F36(rmack RMACK, errors ...secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 36, false, secs2.L(secs2.U1(uint8(rmack)), secs2.L(errors...)))
}

// S15F37 creates the S15F37 (DRNS Segment Approve Action Request) message, direction: bidirectional.
//
// This message is sent by a distributed recipe namespace manager to an attached distributed recipe namespace segment to approve an action previously requested by the segment.
// If multi-block, it shall be preceded by the S15F1/S15F2 inquire/grant transaction.
//
// Body: L[6]{ A[rmsegspec] U4[objtoken] B[rmgrnt] <opid> A[rcpid] <rmchgtype> }.
//
// Exception: None.
func S15F37(rmsegspec string, objtoken uint32, rmgrnt RMGRNT, opid secs2.Item, rcpid string, rmchgtype secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 37, true, secs2.L(secs2.A(rmsegspec), secs2.U4(objtoken), secs2.B(byte(rmgrnt)), opid, secs2.A(rcpid), rmchgtype))
}

// S15F38 creates the S15F38 (DRNS Segment Approve Action Acknowledge) message, direction: bidirectional.
//
// This message is used to acknowledge or deny the approve action request.
//
// Body: L[2]{ U1[rmack] L[n]{ <errors>... } }.
//
// Exception: p = 0 if and only if RMACK indicates no errors.
func S15F38(rmack RMACK, errors ...secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 38, false, secs2.L(secs2.U1(uint8(rmack)), secs2.L(errors...)))
}

// S15F39 creates the S15F39 (DRNS Recorder Segment Request) message, direction: bidirectional.
//
// This message is used by the distributed recipe namespace manager to request that an attached recorder create or delete a segment specifier record.
// If multi-block, it shall be preceded by the S15F1/S15F2 inquire/grant transaction.
//
// Body: L[5]{ <dataid> U1[rmnscmd] A[rmrecspec] A[rmsegspec] U4[objtoken] }.
//
// Exception: None.
func S15F39(dataid secs2.Item, rmnscmd RMNSCMD, rmrecspec string, rmsegspec string, objtoken uint32) secs2.SECS2Message {
	return secs2.NewMessage(15, 39, true, secs2.L(dataid, secs2.U1(uint8(rmnscmd)), secs2.A(rmrecspec), secs2.A(rmsegspec), secs2.U4(objtoken)))
}

// S15F40 creates the S15F40 (DRNS Recorder Segment Acknowledge) message, direction: bidirectional.
//
// This message is used to acknowledge the request to add or delete a segment specifier record.
//
// Body: L[2]{ U1[rmack] L[n]{ <errors>... } }.
//
// Exception: p = 0 if and only if RMACK indicates no errors.
func S15F40(rmack RMACK, errors ...secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 40, false, secs2.L(secs2.U1(uint8(rmack)), secs2.L(errors...)))
}

// S15F41 creates the S15F41 (DRNS Recorder Modify Request) message, direction: bidirectional.
//
// This message is used by a distributed recipe namespace manager to a recorder to store or delete a change request record.
// If multi-block, it shall be preceded by the S15F1/S15F2 inquire/grant transaction.
//
// Body: L[5]{ <dataid> A[rmrecspec] U4[objtoken] U1[rmnscmd] L[1,7]{ A[rcpid] A[rcpnewid] A[rmsegspec] <rmchgtype> <opid> A[timestamp] BOOLEAN[rmrequestor] } }.
//
// Exception: If RMNSCMD = create, then c = 7, otherwise c = 1.
func S15F41(dataid secs2.Item, rmrecspec string, objtoken uint32, rmnscmd RMNSCMD, rcpid string, rcpnewid string, rmsegspec string, rmchgtype secs2.Item, opid secs2.Item, timestamp string, rmrequestor bool) secs2.SECS2Message {
	return secs2.NewMessage(15, 41, true, secs2.L(dataid, secs2.A(rmrecspec), secs2.U4(objtoken), secs2.U1(uint8(rmnscmd)), secs2.L(secs2.A(rcpid), secs2.A(rcpnewid), secs2.A(rmsegspec), rmchgtype, opid, secs2.A(timestamp), secs2.BOOLEAN(rmrequestor))))
}

// S15F41Delete creates the short form of an S15F41 (DRNS Recorder Modify Request) message, direction: bidirectional.
//
// [S15F41] creates the full form,
// and [DecodeS15F41] decodes both.
//
// Body: L[5]{ <dataid> A[rmrecspec] U4[objtoken] U1[rmnscmd] L[1]{ A[rcpid] } }.
func S15F41Delete(dataid secs2.Item, rmrecspec string, objtoken uint32, rmnscmd RMNSCMD, rcpid string) secs2.SECS2Message {
	return secs2.NewMessage(15, 41, true, secs2.L(dataid, secs2.A(rmrecspec), secs2.U4(objtoken), secs2.U1(uint8(rmnscmd)), secs2.L(secs2.A(rcpid))))
}

// S15F42 creates the S15F42 (DRNS Recorder Modify Acknowledge) message, direction: bidirectional.
//
// This message is used to acknowledge a request to store or delete a change request.
//
// Body: L[2]{ U1[rmack] L[n]{ <errors>... } }.
//
// Exception: p = 0 if and only if RMACK indicates no errors.
func S15F42(rmack RMACK, errors ...secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 42, false, secs2.L(secs2.U1(uint8(rmack)), secs2.L(errors...)))
}

// S15F43 creates the S15F43 (DRNS Get Change Request) message, direction: bidirectional.
//
// This message is used to request a distributed recipe namespace recorder or manager to return change requests records for a specific recipe or assigned to a specific segment.
// If multi-block, it shall be preceded by the S15F1/S15F2 inquire/grant transaction.
//
// Body: L[3]{ <dataid> A[objspec] A[targetspec] }.
//
// Exception: If TARGETSPEC is omitted (a zero-length item), OBJSPEC identifies a recipe.
func S15F43(dataid secs2.Item, objspec string, targetspec string) secs2.SECS2Message {
	return secs2.NewMessage(15, 43, true, secs2.L(dataid, secs2.A(objspec), secs2.A(targetspec)))
}

// S15F44 creates the S15F44 (DRNS Get Change Request Data) message, direction: bidirectional.
//
// This message is used to return the specified change request records.
//
// Body: L[2]{ L[n]{ <changes>... } L[2]{ U1[rmack] L[n]{ <errors>... } } }.
//
// Exception: If n = 0, no change records were found matching the specification.
// p = 0 if and only if RMACK indicates no errors.
func S15F44(changes []secs2.Item, rmack RMACK, errors ...secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 44, false, secs2.L(secs2.L(changes...), secs2.L(secs2.U1(uint8(rmack)), secs2.L(errors...))))
}

// S15F45 creates the S15F45 (DRNS Manager Segment Change Approval Request) message, direction: bidirectional.
//
// This message is sent to a distributed recipe namespace manager by an attached distributed recipe namespace segment to request approval for a specific type of change to a recipe.
// If multi-block, it shall be preceded by the S15F1/S15F2 inquire/grant transaction.
//
// Body: L[4]{ <dataid> A[rcpspec] A[rcpnewid] <rmchgtype> }.
//
// Exception: RCPNEWID is a zero-length item except where RMCHGTYPE specifies a copy or rename change.
func S15F45(dataid secs2.Item, rcpspec string, rcpnewid string, rmchgtype secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 45, true, secs2.L(dataid, secs2.A(rcpspec), secs2.A(rcpnewid), rmchgtype))
}

// S15F46 creates the S15F46 (DRNS Manager Segment Approval Acknowledge) message, direction: bidirectional.
//
// This message is used to acknowledge the request to change a recipe.
//
// Body: L[3]{ <rmchgtype> B[rmgrnt] <opid> }.
//
// Exception: OPID is zero if and only if RMGRNT indicates the change is denied.
func S15F46(rmchgtype secs2.Item, rmgrnt RMGRNT, opid secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 46, false, secs2.L(rmchgtype, secs2.B(byte(rmgrnt)), opid))
}

// S15F47 creates the S15F47 (DRNS Manager Rebuild Request) message, direction: bidirectional.
//
// This message requests a distributed recipe namespace manager specified in OBJSPEC to rebuild a distributed recipe namespace.
// Either a distributed recipe namespace recorder or a list of distributed recipe namespace segment specifiers shall be provided.
// If multi-block, it shall be preceded by the S15F1/S15F2 inquire/grant transaction.
//
// Body: L[5]{ <dataid> A[objspec] A[rmnsspec] A[rmrecspec] L[n]{ <segments>... } }.
//
// Exception: If RMRECSPEC is a non-zero length item, then n is zero.
// If RMRECSPEC is a zero length item, then n is non-zero.
func S15F47(dataid secs2.Item, objspec string, rmnsspec string, rmrecspec string, segments ...secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 47, true, secs2.L(dataid, secs2.A(objspec), secs2.A(rmnsspec), secs2.A(rmrecspec), secs2.L(segments...)))
}

// S15F48 creates the S15F48 (DRNS Manager Rebuild Acknowledge) message, direction: bidirectional.
//
// This message is used to acknowledge the request to rebuild a distributed recipe namespace.
//
// Body: L[2]{ U1[rmack] L[n]{ <errors>... } }.
//
// Exception: p = 0 if and only if RMACK indicates no errors.
func S15F48(rmack RMACK, errors ...secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 48, false, secs2.L(secs2.U1(uint8(rmack)), secs2.L(errors...)))
}

// S15F49 creates the S15F49 (Large Recipe Download Request) message, direction: host-to-equipment.
//
// This is a request by the host for the equipment to request the download of a recipe via the Stream 13 Data Set Transfer protocol.
// The Data Set name, DSNAME, is the text string identifier of the recipe, RCPSPEC.
// The Data Set is subsequently transferred as a Stream with the internal SECS-II structure L,4 of RCPSPEC, DATAID, a list of RCPATTRID/RCPATTRDATA pairs,
// and RCPBODY.
//
// Body: L[2]{ A[dsname] BOOLEAN[rcpowcode] }.
//
// Exception: None.
func S15F49(dsname string, rcpowcode bool) secs2.SECS2Message {
	return secs2.NewMessage(15, 49, true, secs2.L(secs2.A(dsname), secs2.BOOLEAN(rcpowcode)))
}

// S15F50 creates the S15F50 (Large Recipe Download Acknowledge) message, direction: equipment-to-host.
//
// Acknowledge or error.
// A returned status of "accepted" means only that the message is understood.
// Upon completion of the large recipe download request (Stream 13 Data Set transfer scenario) the equipment initiates a separate verification transaction (S15F53/S15F54)
// that provides the result of the verification.
//
// Body: B[ackc15].
//
// Exception: None.
func S15F50(ackc15 ACKC15) secs2.SECS2Message {
	return secs2.NewMessage(15, 50, false, secs2.B(byte(ackc15)))
}

// S15F51 creates the S15F51 (Large Recipe Upload Request) message, direction: host-to-equipment.
//
// This is a request by the host for the equipment to request the host to upload a recipe via the Stream 13 Data Set Transfer protocol.
// The Data Set name, DSNAME, is the text string identifier of the recipe, RCPSPEC.
// The Data Set is subsequently transferred as a Stream with the internal SECS-II structure L,3 of RCPSPEC, a list of RCPATTRID/RCPATTRDATA pairs,
// and RCPBODY.
//
// Body: A[dsname].
//
// Exception: None.
func S15F51(dsname string) secs2.SECS2Message {
	return secs2.NewMessage(15, 51, true, secs2.A(dsname))
}

// S15F52 creates the S15F52 (Large Recipe Upload Acknowledge) message, direction: equipment-to-host.
//
// Acknowledge or error.
// A returned status of "accepted" means only that the message is understood.
// The completion of the request is signaled by an event report.
//
// Body: B[ackc15].
//
// Exception: It is possible to use the ACKC15 code "command will be performed with completion signaled later" for this message.
func S15F52(ackc15 ACKC15) secs2.SECS2Message {
	return secs2.NewMessage(15, 52, false, secs2.B(byte(ackc15)))
}

// S15F53 creates the S15F53 (Recipe Verification Send) message, direction: equipment-to-host.
//
// This message indicates to the host that a large recipe that was transferred via Stream 13 Data Set Transfer Protocol had been received
// and checked by the equipment.
// RCPID contains the identifier of a derived object form recipe if created during verification.
// The result of the check is specified by the list of errors.
// An empty error list indicates no errors were found in the recipe.
// The equipment is responsible for sending a single copy of this message to the host after any reception of a recipe through S15F49.
//
// Body: L[3]{ A[rcpspec] A[rcpid] L[2]{ U1[rmack] L[n]{ <errors>... } } }.
//
// Exception: n = 0 if and only if RMACK indicates no error.
// If RCPSPEC is a zero length item, then the recipe was not verified or failed verification.
// If RCPID is zero length, then no derived object form recipe was originated.
func S15F53(rcpspec string, rcpid string, rmack RMACK, errors ...secs2.Item) secs2.SECS2Message {
	return secs2.NewMessage(15, 53, true, secs2.L(secs2.A(rcpspec), secs2.A(rcpid), secs2.L(secs2.U1(uint8(rmack)), secs2.L(errors...))))
}

// S15F54 creates the S15F54 (Recipe Verification Acknowledge) message, direction: host-to-equipment.
//
// Reply by host to equipment providing response to Recipe Verification Send (RVS).
//
// Body: Header only.
//
// Exception: None.
func S15F54() secs2.SECS2Message {
	return secs2.NewMessage(15, 54, false, secs2.NewEmptyItem())
}
